<script>
  import { onMount } from 'svelte'
  import { emit, listen } from '@tauri-apps/api/event'
  import {
    invokeModule,
    listModules,
    onModuleError,
    onModuleLoaded,
    onModuleReloaded,
    reloadModule
  } from 'tauri-plugin-wasm-backend-api'
  // Typed client generated by the plugin from the module's WIT exports
  // (`typescriptOutDir` in tauri.conf.json); regenerated on every reload.
  import { greeter } from './lib/wasm/greeter'
  import Greet from './lib/Greet.svelte'

  let name = $state('')
  let age = $state(30)
  let numbers = $state('3, 1, 4, 1, 5, 9, 2, 6')
  let modules = $state([])
  let log = $state([])

  function append(entry) {
    const text = typeof entry === 'string' ? entry : JSON.stringify(entry)
    log = [`[${new Date().toLocaleTimeString()}] ${text}`, ...log].slice(0, 50)
  }

  async function refresh() {
    modules = await listModules()
  }

  onMount(() => {
    refresh()
    const unlisten = [
      onModuleLoaded((m) => (append(`loaded ${m.name}`), refresh())),
      onModuleReloaded((m) => (append(`hot reloaded ${m.name} (generation ${m.generation})`), refresh())),
      onModuleError((e) => append(`module error in ${e.module}: ${e.error}`)),
      listen('greeter://greeted', (e) => append({ event: 'greeter://greeted', payload: e.payload })),
      listen('greeter://pong', (e) => append({ event: 'greeter://pong', payload: e.payload })),
      listen('stats://computed', (e) => append({ event: 'stats://computed', payload: e.payload }))
    ]
    return () => unlisten.forEach((p) => p.then((f) => f()))
  })

  const run = (promise) => promise.then(append).catch((e) => append(`error: ${JSON.stringify(e)}`))

  // Typed: `greet(name: string): Promise<string>`.
  const greetWasm = () => run(greeter.greet(name || 'World'))
  // `result<string, string>`: the err case rejects the promise.
  const describe = () => run(greeter.describe({ name, ageYears: Number(age) }))
  const increment = () => run(greeter.increment(1))
  // Untyped: an Extism module written in Rust.
  const summarize = () =>
    run(invokeModule('stats', 'summarize', { numbers: numbers.split(',').map(Number).filter((n) => !isNaN(n)) }))
  // Delivered to the greeter's `on-event` export (`events.listen` capability).
  const ping = () => emit('app://ping', { from: 'frontend' })
</script>

<main class="container">
  <h1>Tauri + WASM backend</h1>

  <div class="row">
    <Greet />
  </div>

  <section>
    <h2>greeter <small>(JavaScript → WIT component)</small></h2>
    <div class="row">
      <input placeholder="Name" bind:value={name} />
      <input type="number" bind:value={age} style="width: 5em" />
    </div>
    <div class="row">
      <button onclick={greetWasm}>greet</button>
      <button onclick={describe}>describe</button>
      <button onclick={increment}>increment</button>
      <button onclick={ping}>emit app://ping</button>
    </div>
  </section>

  <section>
    <h2>stats <small>(Rust → Extism plugin)</small></h2>
    <div class="row">
      <input bind:value={numbers} />
      <button onclick={summarize}>summarize</button>
    </div>
  </section>

  <section>
    <h2>Modules</h2>
    {#each modules as m}
      <div class="module">
        <strong>{m.name}</strong> · {m.engine} · generation {m.generation}{m.watched ? ' · watching' : ''}
        <button onclick={() => run(reloadModule(m.name).then((r) => `reloaded ${r.name}`))}>reload</button>
        <div class="commands">
          {#each m.commands as c}
            <code>{c.name}({c.params.map((p) => `${p.name}: ${p.type}`).join(', ')}){c.result ? ` -> ${c.result}` : ''}</code>
          {/each}
        </div>
      </div>
    {/each}
  </section>

  <section>
    <h2>Log</h2>
    <pre>{log.join('\n')}</pre>
  </section>
</main>

<style>
  section {
    margin-top: 1.5em;
  }
  h2 small {
    font-weight: normal;
    opacity: 0.7;
  }
  .row {
    gap: 0.5em;
    margin-bottom: 0.5em;
  }
  .module {
    text-align: left;
    margin: 0.5em auto;
    max-width: 40em;
  }
  .commands code {
    display: block;
    font-size: 0.85em;
  }
  pre {
    text-align: left;
    max-width: 40em;
    margin: 0 auto;
    white-space: pre-wrap;
  }
</style>
